Here is a sample program that reads a text file line by line and counts the number of occurrences of a specific word in the file:
```
#include <iostream>
#include <fstream>
#include <string>
using namespace std;
int main() {
    string word, filename, searchWord;
    int count = 0;
    cout << "Enter the filename: ";
    getline(cin, filename);
    ifstream input(filename);
    if (!input) {
        cout << "Error: File could not be opened." << endl;
        return 1;
    }
    cout << "Enter the word to search for: ";
    getline(cin, searchWord);
    while (input) {
        getline(input, word);
        size_t pos = word.find(searchWord);
        if (pos!= string::npos) {
            count++;
        }
    }
    input.close();
    cout << "The word '" << searchWord << "' appears " << count 
         << " times in the file." << endl;
    return 0;
}
```
This program prompts the user to enter a filename and a word to search for, then reads the file line by line and counts the number of occurrences of the specified word. It displays the result at the end.user

